USE eventra;
-- Generate the admin hash with: node -e "console.log(require('bcryptjs').hashSync('Admin@123',10))"
SELECT e.id, CONCAT('A', n), 'A', n FROM events e JOIN (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8) seats
WHERE e.name='Spring Beats' AND NOT EXISTS (SELECT 1 FROM event_seats WHERE event_id=e.id);
